# Generates microprocessors lesson 9 (command format) from lecture 9 (ENU), with +сызба +слайд.
import json,os,re,sys
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from lib import T,TL,B,A,P,S,F,IMG
from sym import L,R
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT=f'{ROOT}/courses/microprocessors'
SL=f'{ROOT}/tools/slides-09'
course={"id":"microprocessors","name":"Микропроцессорлық жүйелер","lang":"kk","space":"courses"}
def H(t):return f'<h2>{t}</h2>'
def LEAD(t):return f'<p class="lead">{t}</p>'
def Pp(t):return f'<p>{t}</p>'
def UL(items,tag='ul'):return f'<{tag}>'+''.join(f'<li>{i}</li>' for i in items)+f'</{tag}>'
def TAB(rows,head):return '<table><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def AN(t):return f'<aside class="analogy"><p>{t}</p></aside>'
def PF(t):return f'<aside class="pitfall"><p>{t}</p></aside>'
def CHECK(q,a):return f'<aside class="check"><p class="q">{q}</p><div class="a">{a}</div></aside>'
def DEM(t):return f'<p><b>Демек: {t}</b></p>'
def img(name,alt,cap):return IMG(f'{SL}/{name}',alt,cap)

# ---------- numbers, recomputed ----------
OP,AD,RG,WORD=4,12,3,16
full=OP+4*AD; three=OP+3*AD; two=OP+2*AD; one=OP+AD; regs=OP+2*RG
assert (full,three,two,one,regs)==(52,40,28,16,10)
assert 2**AD==4096 and 2**RG==8 and 2**OP==16
ceil=lambda a,b:-(-a//b)
assert ceil(full,8)==7 and ceil(full,16)==4 and ceil(three,8)==5 and ceil(three,16)==3 and ceil(two,16)==2 and ceil(one,16)==1 and ceil(regs,16)==1
assert 3*one==48 and 4*one==64 and 2*three==80 and ceil(three,16)*2==6
assert full-three==AD and three-two==AD and two-one==AD and two-regs==18
assert 2*two==56 and 2*ceil(two,16)==4
assert int('000001100100',2)==100 and 0b0011==3
assert 5+3==8
assert 2**4==16>=13 and OP+2*4==12  # 16 registers -> 4-bit field
# final task: word 16, 32 commands, 256 cells, 8 registers
K,Ad=5,8
assert 2**K==32 and 2**Ad==256
t3=K+3*Ad; o1=K+Ad
assert (t3,o1)==(29,13) and ceil(t3,16)==2 and ceil(o1,16)==1
assert 2*ceil(t3,16)==4 and 4*ceil(o1,16)==4 and 3*2==6 and 4*1==4

