    qs=['не\nістеу?','1-ші сан\nқайда?','2-ші сан\nқайда?','нәтиже\nқайда?','келесі\nқайда?']
    x=10;o=''
    for i,(w,n,q) in enumerate(zip(ws,names,qs)):
        o+=B(x,12,w-2,46,n,'bxa' if i==0 else 'bx','t-s t-b',lh=14)
        o+=A(x+w/2-1,60,x+w/2-1,84)
        for k,l in enumerate(q.split('\n')):o+=T(x+w/2-1,102+k*14,l,'t-s')
        x+=w
