def fig_len():
    s=5;x0=10;o=''
    flds=[('КОП',4,'bxa'),('адр.1',12,'bx'),('адр.2',12,'bx'),('нәтиже',12,'bx'),('келесі',12,'soft')]
    x=x0
    for n,b,c in flds:
        o+=R(x,26,b*s,26,c,2)+T(x+b*s/2,18,n,'t-s')+T(x+b*s/2,44,str(b),'t-s t-b');x+=b*s
    # brackets
    o+=L(x0,62,x0+three*s,62,'lna')+T(x0+three*s/2,78,'40 бит (лекциядағы есеп)','t-s')
    o+=L(x0,90,x0+full*s,90,'lna')+T(x0+full*s/2,106,'52 бит (келесі адреспен)','t-s t-b')
    # words
    for k in range(4):o+=R(x0+k*WORD*s,122,WORD*s,22,'soft',1)
    o+=R(x0,122,full*s,22,'bxa',1)
    for k in range(4):o+=T(x0+k*WORD*s+WORD*s/2,137,f'{k+1}-сөз','t-s' if k<3 else 't-s')
    o+=TL(10,164,'әр жақтау — 16 биттік сөз; 52 бит төрт сөзді алады','t-s mu')
    return o
f_len=F(S(340,174,fig_len(),'Толық команданың ұзындығы'),'Өрістердің ені биттермен берілген: КОП 4 бит, әр адрес 12 бит. Төменде осы команда 16 биттік сөздерге қалай жатады')

def fig_pc():
    cells=[('100','команда'),('101','команда'),('102','JMP 200'),('…',''),('200','команда')]
    x=10;o='';xs=[]
    for i,(a,t) in enumerate(cells):
        c='bxa' if i==2 else 'bx'
        o+=R(x,24,50,36,c,3)+T(x+25,40,a,'t-s t-b')+T(x+25,54,t,'t-s')
        xs.append(x);x+=68
    o+=TL(10,16,'адрес және ұяшықтағы команда','t-s mu')
    o+=A(xs[0]+50,42,xs[1],42)+A(xs[1]+50,42,xs[2],42)+T(xs[0]+59,36,'+1','t-s ac')+T(xs[1]+59,36,'+1','t-s ac')
    o+=P([(xs[2]+25,60),(xs[2]+25,92),(xs[4]+25,92),(xs[4]+25,62)],'lna','hda')
    o+=T((xs[2]+xs[4])/2+25,110,'JMP PC-ға 200 жазады','t-s ac')
    o+=TL(10,150,'PC: 100 → 101 → 102 → 200','t-s t-b')
    return o
f_pc=F(S(340,160,fig_pc(),'Командалар санауышы және ауысу'),'Командалар санауышы (PC) ретімен +1 өседі; ауысу командасы PC-ға жаңа адрес жазады')

